"""Aggregate the predetermined run and evaluations, preserving all episode outcomes."""
import csv,gzip,json,statistics,subprocess
from collections import Counter
from pathlib import Path
OUT=Path('/var/tmp/typhon-research-20261011/broad-pt')
METHODS=['narrow-m6-3000','broad-pt-3000','broad-pt-12000']
def dump(path,value):path.write_text(json.dumps(value,indent=2,allow_nan=False)+'\n')
def add_70mm_metric(folder,row):
 episode=json.loads((folder/row['id']/'episode.json').read_text());z0=episode['initial_truth']['object_position_m'][2]
 records=[json.loads(x)['truth'] for x in gzip.open(folder/row['id']/'trajectory.jsonl.gz','rt')]
 flags=[bool(x['bilateral_grasp_contact']) and x['object_position_m'][2]-z0>=.07 for x in records]
 longest=current=0
 for yes in flags:
  current=current+1 if yes else 0;longest=max(longest,current)
 row.update(bilateral_lift_70mm_any=any(flags),bilateral_lift_70mm_3steps=longest>=3,bilateral_lift_70mm_steps=sum(flags),longest_bilateral_lift_70mm_s=longest/20)
def main():
 done=json.loads((OUT/'training-complete.json').read_text());assert done['passed'] and done['updates']==12000
 rows=[json.loads(x) for x in (OUT/'train-losses.jsonl').read_text().splitlines()];assert [r['step'] for r in rows]==list(range(1,12001))
 allcount=Counter(x.split(':')[0] for r in rows for x in r['sample_ids']);assert len(allcount)==6 and set(allcount.values())=={8000}
 stage=[]
 for lo,hi in [(1,1000),(1001,2000),(2001,3000),(3001,12000)]:
  rs=rows[lo-1:hi];last=rs[-100:]
  stage.append({'steps':[lo,hi],'updates':len(rs),'sum_update_seconds':sum(r['seconds'] for r in rs),'mean_update_seconds':statistics.mean(r['seconds'] for r in rs),'last100_losses':{k:statistics.mean(r[k] for r in last) for k in ['position_loss','rotate6D_loss','gripper_loss']}})
 training={'passed':True,'contiguous_updates':12000,'actual_samples_per_take':dict(allcount),'stages':stage,'completion':done,'fixed_checkpoints':{str(s):json.loads((OUT/('checkpoint-'+str(s)+'.json')).read_text()) for s in [3000,12000]},'integrity':{str(s):json.loads((OUT/('checkpoint-validation-fixed-'+str(s)+'.json')).read_text()) for s in [3000,12000]}}
 assert all(x['passed'] for x in training['integrity'].values());dump(OUT/'final-training-audit.json',training)
 comparisons=[];episodes=[];fits=[];videos=[];families=[];pooled_fits=[];take_fits=[]
 for method in METHODS:
  folder=OUT/'evaluation'/method;complete=json.loads((folder/'complete.json').read_text());assert complete['completed']
  reload=json.loads((folder/'reload-verification.json').read_text());assert reload['passed'] and reload['action_max_error']==0
  rs=json.loads((folder/'summary.json').read_text());assert len(rs)==6
  assert all(not r['errors'] for r in rs),'Any runtime failure must be handled explicitly before aggregating'
  for row in rs:add_70mm_metric(folder,row)
  r={'method':method,'trials':len(rs),'strict_successes':sum(x['success'] for x in rs),'supported_grasps':sum(x['supported_lift_10mm_3steps'] for x in rs),'supported_grasps_70mm_any':sum(x['bilateral_lift_70mm_any'] for x in rs),'supported_grasps_70mm_3steps':sum(x['bilateral_lift_70mm_3steps'] for x in rs),'footprints_inside':sum(x['footprint_inside_target'] for x in rs),'operational_placements':sum(x['operational_placement'] for x in rs)}
  for k in ['position_error_mm','initial_yaw_error_deg','final_yaw_error_deg','yaw_error_reduction_deg','wall_seconds','eef_path_m']:
   r['mean_'+k]=statistics.mean(x[k] for x in rs)
  for family in sorted({x['source_demo_id'] for x in rs}):
   frows=[x for x in rs if x['source_demo_id']==family]
   families.append({'method':method,'source_demo_id':family,'trials':len(frows),'strict_successes':sum(x['success'] for x in frows),'supported_grasps_10mm_3steps':sum(x['supported_lift_10mm_3steps'] for x in frows),'supported_grasps_70mm_any':sum(x['bilateral_lift_70mm_any'] for x in frows),'supported_grasps_70mm_3steps':sum(x['bilateral_lift_70mm_3steps'] for x in frows),'inside_count':sum(x['footprint_inside_target'] for x in frows),'operational_placement_count':sum(x['operational_placement'] for x in frows),**{'mean_'+k:statistics.mean(x[k] for x in frows) for k in ['position_error_mm','initial_yaw_error_deg','final_yaw_error_deg','yaw_error_reduction_deg','wall_seconds']}})
  own=[x for x in families if x['method']==method]
  r['independent_scene_families']=len(own);r['family_macro_success_rate']=statistics.mean(x['strict_successes']/x['trials'] for x in own);r['family_macro_grasp_10mm_rate']=statistics.mean(x['supported_grasps_10mm_3steps']/x['trials'] for x in own)
  for k in ['position_error_mm','initial_yaw_error_deg','final_yaw_error_deg','yaw_error_reduction_deg']:
   r['family_macro_'+k]=statistics.mean(x['mean_'+k] for x in own)
  comparisons.append(r)
  for x in rs:
   episodes.append({k:x[k] for k in ['method','id','source_demo_id','seed','success','supported_lift_10mm_3steps','footprint_inside_target','operational_placement','position_error_mm','initial_yaw_error_deg','final_yaw_error_deg','yaw_error_reduction_deg','wall_seconds','eef_path_m','maximum_lift_above_initial_mm','longest_supported_lift_s','bilateral_lift_70mm_any','bilateral_lift_70mm_3steps','bilateral_lift_70mm_steps','longest_bilateral_lift_70mm_s']})
   video=folder/x['id']/'rollout.mp4';probe=json.loads(subprocess.check_output(['ffprobe','-v','error','-select_streams','v:0','-show_entries','stream=nb_frames,width,height,duration','-of','json',str(video)],text=True));assert probe['streams'] and int(probe['streams'][0]['nb_frames'])>1
   cp=subprocess.run(['ffmpeg','-v','error','-i',str(video),'-f','null','-'],capture_output=True,text=True);assert cp.returncode==0 and not cp.stderr,(video,cp.stderr)
   videos.append({'path':str(video),'full_decode_passed':True,**probe['streams'][0]})
  fit=json.loads((folder/'teacher-forced/summary.json').read_text())
  take_fits.extend({'method':method,**r} for r in fit['takes'])
  windows=[json.loads(x) for x in (folder/'teacher-forced/windows.jsonl').read_text().splitlines()]
  for split in ['P_train','P_validation']:
   ws=[x for x in windows if x['split']==split]
   pooled_fits.append({'method':method,'split':split,'windows':len(ws),'aggregation':'pooled windows, correlated within take',**{k:statistics.mean(x[k] for x in ws) for k in ['xyz_mean_mm','xyz_rmse_mm','wrist_rotation_mean_deg','gripper_probability_mae','gripper_binary_accuracy']}})

  for split,row in fit['splits'].items():fits.append({'method':method,'split':split,**{k:v for k,v in row.items() if k!='native_forward_losses'},**row['native_forward_losses']})
  one=next(r for r in fit['takes'] if r['episode']=='personal_demo_0001');fits.append({'method':method,'split':'personal0001 narrow-seen','independent_takes':1,**{k:v for k,v in one.items() if k not in ['episode','split','windows','native_forward_losses']},**one['native_forward_losses']})
 for name,data in [('comparisons.csv',comparisons),('episodes.csv',episodes),('family-comparisons.csv',families),('teacher-forced-comparisons.csv',fits),('teacher-forced-pooled-windows.csv',pooled_fits)]:
  with (OUT/name).open('w',newline='') as f:w=csv.DictWriter(f,fieldnames=list(data[0]));w.writeheader();w.writerows(data)
 dump(OUT/'video-validation.json',videos)
 dump(OUT/'per-take-fit.json',take_fits)
 dump(OUT/'family-outcomes.json',families)
 summary={'complete':True,'training':training,'comparisons':comparisons,'teacher_forced':fits,'teacher_forced_pooled_windows':pooled_fits,'teacher_forced_per_take':take_fits,'per_family_physical':families,'statistical_scope':'3 previously inspected development scene families x2paired stochastic seeds,3models; no checkpoint selection, no significance claim','videos_decoded':len(videos)}
 dump(OUT/'validation_summary.json',summary)
 lines=['# Broader Pt adaptation: measured outcomes','','One full-weight run used all six frozen P_train takes. Both predetermined checkpoints are reported. The original narrow M6 is rerun with the same native O2 observation/action contract, holdout scenes, two seeds, and step budget.','','| Model | Strict success | Grasp ≥10mm/3steps | Grasp ≥70mm/3steps | In square | Released stable placement | Mean position error | Mean final yaw error | Mean yaw-error reduction |','|---|---:|---:|---:|---:|---:|---:|---:|---:|']
 for r in comparisons:
  n=r['trials'];lines.append(f"| {r['method']} | {r['strict_successes']}/{n} | {r['supported_grasps']}/{n} | {r['supported_grasps_70mm_3steps']}/{n} | {r['footprints_inside']}/{n} | {r['operational_placements']}/{n} | {r['mean_position_error_mm']:.1f} mm | {r['mean_final_yaw_error_deg']:.1f}° | {r['mean_yaw_error_reduction_deg']:.1f}° |")
 lines+=['','Supported grasp requires a lift of at least 10 mm with simultaneous bilateral contact for at least three consecutive control steps. The added ≥70mm column also requires simultaneous bilateral contact for three consecutive steps and is derived from retained traces; the preregistered ≥10mm threshold remains primary. Single-step ≥70mm bilateral counts are included separately in comparisons.csv for cross-branch comparison. In-square means the whole brick footprint is inside the target; released stable placement additionally checks face-up, height, release, and stability. Strict success also requires the supplied orientation tolerance. Yaw-error reduction is initial absolute goal error minus final absolute goal error; positive is improvement. These are brick metrics, distinct from the wrist action-fit metrics below.','','| Model | Split | EEF XYZ error | Wrist rotation error | Gripper accuracy |','|---|---|---:|---:|---:|']
 for r in fits:lines.append(f"| {r['method']} | {r['split']} | {r['xyz_mean_mm']:.1f} mm | {r['wrist_rotation_mean_deg']:.1f}° | {100*r['gripper_binary_accuracy']:.1f}% |")
 lines+=['','Teacher-forced results use expert-conditioned observations/history reset at each fixed window, with identical per-window noise seeds across models. The 68 train and 33 holdout windows are averaged per take and then equally over takes. They measure action-target fit, not closed-loop success. The six-take P_train pool is the broad model training set; only take0001 was seen by narrow M6, so its result on that single take is shown separately.','','Per-take fit records are in per-take-fit.json; pooled-window numbers are separately labelled in teacher-forced-pooled-windows.csv. Physical per-family outcomes and equally weighted family averages are in family-comparisons.csv and comparisons.csv. Because there are exactly two seeds per family, physical pooled and family-macro rates agree here. The 18 rollouts contain only three development scene families, each repeated twice per model. This panel cannot establish statistically reliable generalization. Training changes source breadth, window coverage, and sampling together; 12k also changes update budget. All six sources are successful expert trajectories with the same zero-yaw goal; no failed-state recovery or human pause timing was added.','','The original phone data supplied scene endpoints; robot RGB/action supervision was generated by the Panda expert. No direct phone-to-robot frame alignment or learned retargeting is claimed.','','Every model passed an exact fresh-process action-probe reload. All 18 videos fully decoded, and raw chunks, inputs, telemetry, and independent scorer outputs remain under evaluation/. Training completed with source hashes and inactive domain rows unchanged. The invalid 2k quota-truncated recovery is quarantined; the same live weights continued through the storage repair. See TRAINING_REPORT.md, comparability-audit.json, and storage-correction.json for the full recipe and limitations.']
 motion=json.loads((OUT/'motion-diagnostics.json').read_text())
 lines+=['','## Interpretation','','Broader adaptation substantially improves supervised action-target fit on the six source takes. At the fixed 3k budget, holdout XYZ and wrist errors also fall relative to the original narrow model. This does not translate into a grasp or placement in these development scenes. Extending the broader run to 12k reduces source-pool XYZ error from 34.9 to 11.7 mm, while holdout error changes only from 120.6 to 119.5 mm and wrist error changes from 30.6 to 31.5 degrees. This is a training/holdout fit gap with no demonstrated closed-loop benefit; it does not establish a single causal explanation such as overfitting.','','The retained action traces localize the failure earlier than orientation or release: none of the 18 rollouts makes bilateral grasp contact or changes the brick position. Both broader checkpoints command closure on take0014, in both seeds, but close without grasping the brick; neither commands closure on0006 or0016. Narrow M6 never commands closure on these six trials. Broader 3k moves nearer the object in two of the three families, but never reaches an actual grasp. The native model-controller chain is not being stopped by an added harness. Requested and applied environment actions agree at every saved model-driven step; this does not eliminate upstream native controller clipping or tracking error as possible contributors.','','| Model | Take | Nearest executed EEF-to-brick-centre distance, seed mean | Close-command steps across both seeds |','|---|---|---:|---:|']
 for method in METHODS:
  for family in sorted({r['source_demo_id'] for r in motion['rows']}):
   selected=[r for r in motion['rows'] if r['method']==method and r['source_demo_id']==family]
   assert len(selected)==2
   lines.append(f"| {method} | {family} | {statistics.mean(r['minimum_eef_to_object_centre_mm'] for r in selected):.1f} mm | {sum(r['target_close_command_steps'] for r in selected)} |")
 lines+=['','These exploratory distance diagnostics use the object centre, not a newly defined grasp threshold. They exclude the separate 24 terminal stability steps. Full per-seed distances, command probabilities and tracking errors are in motion-diagnostics.json. The source trajectories contain successful progression, so fit on expert inputs cannot by itself validate recovery from the model’s own approach errors. An initial exploratory counter inspected unused gripper slot19; corrected outputs use active Panda slot9 and assert every resulting binary command against the controller request. The invalid counts and correction receipt are preserved in invalidated-diagnostics/. Training, execution, physical scores and the original fit diagnostic were unaffected.','','The separately authorized post-hoc source diagnostic is now complete: fixed12k achieves6/6 supported pickups,5/6 released stable placements inside the square, and4/6 strict successes on its six exact training starts. Take0001 stalls while holding the brick;0005 misses only the strict15mm centre tolerance at15.80mm. These are familiar-source results, with no narrow3k or broad3k comparator. They must not replace the primary heldout comparison. See source-competence/SOURCE_COMPETENCE_REPORT.md. This rules out universal inability of the model-controller pair to grasp, while leaving a substantial source-to-holdout gap. Prioritize verified off-trajectory approach and grasp-transition teaching and evaluation on new source groups; additional updates on the same six successful paths alone have not solved the measured holdout failure. This is a recommendation, not another training run or a claim that DAgger will succeed.','','## Saved visual evidence','','![Paired checkpoint comparison](figures/checkpoint-comparison.png)','','The scientific figure shows primary counts and paired position/yaw errors. Initial required yaw correction is labelled separately from the final residual. There are no significance bars. The raw outcome tables remain primary.','','![Representative endpoint images](figures/representative-endpoints.jpg)','','The endpoint contact sheet uses fixed seed7417 for all three families and both original camera views. Agent visual inspection confirms that the brick remains in its original position while arm poses differ. This is endpoint inspection, not a human review of every video. All full videos were separately decoded without error.','','CPU reproduction after the existing evaluated artifacts are present:','','```bash','.venv-sim/bin/python scripts/exp20261011_train_motion_audit.py','.venv-sim/bin/python scripts/exp20261011_train_report.py','.venv-sim/bin/python scripts/exp20261011_train_figure.py','```']
 (OUT/'EVALUATION_REPORT.md').write_text('\n'.join(lines)+'\n');print(json.dumps(comparisons,indent=2))
if __name__=='__main__':main()
